function showInfo(key,anchor){if(infoAnchor===anchor&&!$('#selection-info').hidden){closeInfo(true);return;}closeInfo();let title,description='',plus,minus,compare='';
 if(key.startsWith('plane-')){const id=key.slice(6),d=planeDesign(state);if(id==='architecture'||id==='tail'){const item=id==='architecture'?d.architecture:d.tail;title=item.name;plus=item.pros;minus=item.cons;description=id==='tail'?'Kuyruk yüzeyleri seçilen gövde düzeniyle birlikte değerlendirilir.':item.short;}else [title,description,plus,minus]=PARAM_HELP[id]||['Tasarım bilgisi','','',''];}
 else{const part=selected(state)[key];title=part?.label||part?.name||groupTitle(key);description=part?.description||(part?specs(key,part):'Bu parça henüz seçilmedi. Seçenekleri karşılaştırarak başlayabilirsin.');[plus,minus]=choiceInfo(key,part||{});compare=key;if(key==='extras'){description=state.extras.map(id=>EXTRAS.find(x=>x.id===id)?.name).join(' · ')||'İsteğe bağlı GPS, telemetri ve kamera.';if(state.type==='plane'&&state.extras.includes('camera'))description+=' Kamera burun ucundaki özel kesite oturur.';}}
 $('#selection-info-title').textContent=title;$('#selection-info-content').innerHTML=`<p>${description}</p><p class="tradeoff plus">＋ ${plus}</p><p class="tradeoff minus">− ${minus}</p>${compare?`<button class="wide" data-open-picker="${compare}"${flight?' disabled':''}>Seçenekleri karşılaştır →</button>`:''}`;
 const box=$('#selection-info'),r=anchor.getBoundingClientRect(),width=Math.min(320,window.innerWidth-24);box.style.width=width+'px';box.style.left=Math.max(12,Math.min(r.left,window.innerWidth-width-12))+'px';box.hidden=false;const h=box.getBoundingClientRect().height||250;box.style.top=Math.max(12,r.bottom+8+h>window.innerHeight?r.top-h-8:r.bottom+8)+'px';infoAnchor=anchor;anchor.setAttribute('aria-expanded','true');box.focus({preventScroll:true});
}
function availableGroups(){return GROUPS.filter(([k])=>!k.startsWith('lift')||(state.type==='plane'&&planeDesign(state).architecture.lift));}
