  const groups=availableGroups(),mechanicalKeys=['frame'];$('#build-scope').hidden=state.type!=='plane';$('#plane-design').hidden=state.type!=='plane'||partScope!=='mechanics';document.querySelectorAll('[data-scope]').forEach(b=>{b.classList.toggle('active',b.dataset.scope===partScope);b.setAttribute('aria-selected',b.dataset.scope===partScope);});
